/**
 * Find the longest word in a sentence
 * @param {string} sentence - The input sentence
 * @returns {string} - The longest word found
 */
function findLongestWord(sentence) {
  // Edge cases
  if (!sentence || typeof sentence !== 'string' || sentence.trim().length === 0) {
    return '';
  }

  // Split by spaces and filter empty strings
  const words = sentence.split(/\s+/).filter(word => word.length > 0);

  // Initialize variables
  let longestWord = '';
  let longestLength = 0;

  // Iterate through each word
  for (const word of words) {
    // Remove punctuation for accurate length comparison
    const cleanWord = word.replace(/[.,!?;:'"(){}[\]<>@#$%^&*_+=~`|\\/]/g, '');

    // Update if current word is longer
    if (cleanWord.length > longestLength) {
      longestWord = cleanWord;
      longestLength = cleanWord.length;
    }
  }

  return longestWord;
}

// Alternative: Using reduce (shorter)
const findLongestWordCompact = (sentence) => {
  return sentence?.split(/\s+/)
    .filter(Boolean)
    .reduce((longest, current) => {
      const clean = current.replace(/\W/g, '');
      const cleanLongest = longest.replace(/\W/g, '');
      return clean.length > cleanLongest.length ? current : longest;
    }, '') || '';
};

// Test cases
const testCases = [
  "The quick brown fox jumps over the lazy dog",
  "JavaScript is amazing and powerful",
  "Hello, world!",
  "A B C D E",
  "",
  null,
  "  ",
  "What's the longest word?",
];

testCases.forEach((test, i) => {
  const result = findLongestWord(test);
  console.log(`Test ${i + 1}: "${test}" => "${result}" (length: ${result.length})`);
});
```

## Approach

1. **Input validation** â€” Check for null, undefined, empty, or non-string inputs
2. **Split the sentence** â€” Use regex `\s+` to split on one or more whitespace characters
3. **Filter empty strings** â€” Ensure we only process actual words
4. **Iterate with tracking** â€” Maintain the current longest word and its length
5. **Handle punctuation** â€” Strip punctuation before comparing lengths

## Edge Cases Handled

| Edge Case | Why Important | How Handled |
|-----------|--------------|-------------|
| Empty string | Should return empty string | Early return |
| null/undefined | Avoid crashes | Truthy check |
| Multiple spaces | "Hello   world" has 3 spaces | Regex `\s+` |
| Punctuation | "friend." vs "friendly" | Remove non-word characters |
| Contractions | "don't" should be 5 letters | `\W` regex keeps apostrophe |
| Single letters | "A B C" â†’ "A" (length 1) | Works naturally |
| Same length words | Returns first found | Deterministic |

## Time & Space Complexity

- **Time**: O(n) â€” We iterate through each word once
- **Space**: O(n) â€” The split array stores all words

