import React, { useState } from 'react';

function SearchableDropdown({ options, onSelect, placeholder }) {
    const [query, setQuery] = useState('');
    const [isOpen, setIsOpen] = useState(false);

    const filtered = query
        ? options.filter(opt =>
            opt.toLowerCase().includes(query.toLowerCase())
          )
        : options;

    return (
        <div className="dropdown">
            <input
                type="text"
                value={query}
                onChange={(e) => {
                    setQuery(e.target.value);
                    setIsOpen(true);
                }}
                onFocus={() => setIsOpen(true)}
                placeholder={placeholder || 'Search...'}
            />
            {isOpen && (
                <ul className="dropdown-menu">
                    {filtered.length === 0 ? (
                        <li className="no-results">No results</li>
                    ) : (
                        filtered.map((opt, i) => (
                            <li key={i} onClick={() => {
                                onSelect(opt);
                                setQuery(opt);
                                setIsOpen(false);
                            }}>{opt}</li>
                        ))
                    )}
                </ul>
            )}
            {isOpen && (
                <div className="overlay" onClick={() => setIsOpen(false)} />
            )}
        </div>
    );
}

export default SearchableDropdown;
```

async/await is syntactic sugar over Promises for handling asynchronous operations.

**The problem**: JavaScript is single-threaded. Network requests, file I/O, timers would freeze the UI.

**Solution**: async/await makes async code look synchronous.

**How it works**:

```javascript
// Without async/await (Promise chain)
function getData() {
    return fetch('/api/user')
        .then(res => res.json())
        .then(user => fetch(`/api/orders/${user.id}`))
        .then(res => res.json())
        .catch(err => console.error(err));
}

// With async/await (much cleaner)
async function getData() {
    try {
        const userRes = await fetch('/api/user');
        const user = await userRes.json();
        const ordersRes = await fetch(`/api/orders/${user.id}`);
        const orders = await ordersRes.json();
        return orders;
    } catch (err) {
        console.error(err);
    }
}
```

**Important**:
- `async` function always returns a Promise
- `await` can only be used inside async functions
- `await` pauses execution until Promise resolves
- Multiple awaits run sequentially unless using Promise.all

**Parallel execution**:
```javascript
const [users, products] = await Promise.all([
    fetch('/api/users').then(r => r.json()),
    fetch('/api/products').then(r => r.json())
]);
```

**Event Loop connection**: async/await leverages the microtask queue. When await is encountered, function is suspended and microtask is queued. After Promise resolves, function resumes.
